package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.special.Beta;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FDistributionImpl.getInitialDomain(double p).
 * Since the method is protected, we use reflection to access it for testing.
 */
public class FDistributionImpl_getInitialDomain_TriageGen0Test {

    /**
     * Helper method to invoke the protected method getInitialDomain via reflection.
     */
    private double invokeGetInitialDomain(FDistributionImpl distribution, double p) throws Exception {
        Method method = FDistributionImpl.class.getDeclaredMethod("getInitialDomain", double.class);
        method.setAccessible(true);
        return (double) method.invoke(distribution, p);
    }

    @Test
    public void testGetInitialDomain_StandardValues() throws Exception {
        // Test with denominator degrees of freedom = 10.0
        // Formula: d / (d - 2.0) = 10.0 / (10.0 - 2.0) = 10.0 / 8.0 = 1.25
        double ddf = 10.0;
        FDistributionImpl fDist = new FDistributionImpl(5.0, ddf);
        double p = 0.5;

        double expected = 1.25;
        double actual = invokeGetInitialDomain(fDist, p);

        Assert.assertEquals("The initial domain calculation is incorrect for ddf=10", expected, actual, 1e-15);
    }






}

